import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
API_KEY = os.getenv("API_KEY")

session = requests.Session()
if API_KEY:
    session.headers["Authorization"] = f"Bearer {API_KEY}"
session.headers["Accept"] = "application/json"

region = os.getenv("REGION", "North America")
product_upc = os.getenv("PRODUCT_UPC", "012345678905")
product_id = os.getenv("PRODUCT_ID")
product_name = os.getenv("PRODUCT_NAME", "")
product_details = os.getenv("PRODUCT_DETAILS", "")

def get(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    return response.json()

version = get("/version")

trends = get("/consumer-trends/overview", params={"region": region})
demographic_preferences = get(
    "/demographics/preferences",
    params={"age": os.getenv("AGE_GROUP", ""), "location": region},
)
product_rating = get(f"/products/{product_upc}/rating")
ingredients = get(f"/products/{product_upc}/ingredients")

# Use the product's category and regions identified as high-demand in the trend results
# when available; otherwise, request the general inventory demand forecast.
trend_data = trends if isinstance(trends, dict) else {}
high_demand_regions = trend_data.get("highDemandRegions") or [region]
product_category = trend_data.get("productCategory") or trend_data.get("category")

demand_forecasts = []
for demand_region in high_demand_regions:
    params = {"region": demand_region}
    if product_category:
        params["category"] = product_category
    if product_id:
        params["productId"] = product_id
    elif product_name:
        params["productName"] = product_name
    demand_forecasts.append(
        get("/inventory/demand-forecast", params=params)
    )

if not product_id:
    search_params = {"productName": product_name} if product_name else {}
    search_results = get("/products/search", params=search_params)
    if isinstance(search_results, dict):
        products = search_results.get("products", [])
    else:
        products = search_results
    for product in products or []:
        if str(product.get("productId", "")) == product_upc or product.get("upc") == product_upc:
            product_id = product.get("productId")
            break
    if not product_id and products:
        product_id = products[0].get("productId")

updated_product = None
if product_id:
    details_parts = [
        product_details,
        f"Consumer trends for {region}: {trends}",
        f"Demographic preferences: {demographic_preferences}",
        f"Sustainability rating: {product_rating}",
        f"Ingredients: {ingredients}",
        f"Inventory demand forecasts: {demand_forecasts}",
    ]
    updated_details = "\n\n".join(part for part in details_parts if part)
    payload = {}
    if product_name:
        payload["productName"] = product_name
    if updated_details:
        payload["details"] = updated_details

    if payload:
        response = session.patch(
            f"{BASE_URL}/products/{product_id}",
            json=payload,
            timeout=30,
        )
        response.raise_for_status()
        updated_product = response.json() if response.content else None

result = {
    "api_version": version,
    "consumer_trends": trends,
    "demographic_preferences": demographic_preferences,
    "sustainability_rating": product_rating,
    "ingredients": ingredients,
    "demand_forecasts": demand_forecasts,
    "updated_product": updated_product,
}
print(result)

