import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

# Retrieve the top-rated sustainable products across categories.
top_response = session.get(f"{BASE_URL}/products/top-rated")
top_response.raise_for_status()
top_data = top_response.json()

# Extract product records and IDs from common response shapes.
if isinstance(top_data, list):
    products = top_data
elif isinstance(top_data, dict):
    products = top_data.get("products", top_data.get("data", []))
else:
    products = []

product_ids = []
for product in products:
    if not isinstance(product, dict):
        continue
    product_id = product.get("productId", product.get("product_id", product.get("id")))
    if product_id is not None and product_id not in product_ids:
        product_ids.append(product_id)

# Fetch detailed product information and pricing for each product.
details = {}
prices = {}
for product_id in product_ids:
    detail_response = session.get(f"{BASE_URL}/products/{product_id}")
    detail_response.raise_for_status()
    details[product_id] = detail_response.json()

    price_response = session.get(f"{BASE_URL}/products/{product_id}/prices")
    price_response.raise_for_status()
    prices[product_id] = price_response.json()

# Request seasonal predictions for the selected products over the next quarter.
prediction_response = session.post(
    f"{BASE_URL}/seasonal-trends/predictions",
    json={
        "productIds": product_ids,
        "period": "next_quarter",
    },
)
prediction_response.raise_for_status()
predictions = prediction_response.json()

# Identify products with differing retailer prices and request suggested price updates.
price_update_requests = []
for product_id, price_data in prices.items():
    if isinstance(price_data, dict):
        retailer_prices = price_data.get("prices", price_data.get("retailers", []))
    elif isinstance(price_data, list):
        retailer_prices = price_data
    else:
        retailer_prices = []

    observed_prices = []
    for entry in retailer_prices:
        if not isinstance(entry, dict):
            continue
        value = entry.get("price")
        if value is not None:
            try:
                observed_prices.append(float(value))
            except (TypeError, ValueError):
                pass

    if len(observed_prices) > 1 and min(observed_prices) != max(observed_prices):
        suggested_price = sum(observed_prices) / len(observed_prices)
        update_response = session.post(
            f"{BASE_URL}/request_update",
            json={
                "productId": product_id,
                "suggestedPrice": suggested_price,
                "reason": "Price discrepancy observed across retailers",
                "retailerPrices": retailer_prices,
            },
        )
        update_response.raise_for_status()
        price_update_requests.append(update_response.json())

result = {
    "topRatedProducts": top_data,
    "productDetails": details,
    "seasonalPredictions": predictions,
    "priceInformation": prices,
    "priceUpdateRequests": price_update_requests,
}
print(result)

